on conflict (external_key) do update set
 name=excluded.name,category=excluded.category,description=excluded.description,
 municipality_id=excluded.municipality_id,parish=excluded.parish,address=excluded.address,
 phone=excluded.phone,source_id=excluded.source_id,source_url=excluded.source_url,
 verification_status=excluded.verification_status,last_verified_at=excluded.last_verified_at,
 is_active=excluded.is_active,updated_at=now();
